import{_ as a,o as i,c as n,a5 as r}from"./chunks/framework.a5no_H3L.js";const k=JSON.parse('{"title":"加壳原理与识别","description":"程序保护的手段里，最「面」上的一层是壳（packer）。壳把整个程序打包、压缩甚至加密，让静态分析在最外层就碰壁。这一章讲壳是什么、怎么工作、如何识别。","frontmatter":{"type":"explanation","level":"advanced"},"headers":[],"relativePath":"reverse-engineering/07-packing/chapter-01-packing-principle.md","filePath":"reverse-engineering/07-packing/chapter-01-packing-principle.md"}'),c={name:"reverse-engineering/07-packing/chapter-01-packing-principle.md"};function p(t,e,s,g,l,d){return i(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="加壳原理与识别" tabindex="-1" data-src-line="2" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md">加壳原理与识别 <a class="header-anchor" href="#加壳原理与识别" aria-label="Permalink to &quot;加壳原理与识别&quot;">​</a></h1><p data-src-line="4" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md">程序保护的手段里，最「面」上的一层是壳（packer）。壳把整个程序打包、压缩甚至加密，让静态分析在最外层就碰壁。这一章讲壳是什么、怎么工作、如何识别。</p><h2 id="_1-壳是什么-为什么要加" tabindex="-1" data-src-line="6" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md">1. 壳是什么，为什么要加 <a class="header-anchor" href="#_1-壳是什么-为什么要加" aria-label="Permalink to &quot;1. 壳是什么，为什么要加&quot;">​</a></h2><p data-src-line="8" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md">壳是包裹在原始程序外面的一层代码。加壳后，磁盘上的文件不再是原始程序，而是「壳 + 被壳处理过的原始程序数据」。它的用途有两类：</p><ul data-src-line="10" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md"><li data-src-line="10" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md"><strong>压缩</strong>：减小文件体积（如 UPX、ASPack）。</li><li data-src-line="11" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md"><strong>保护</strong>：让分析、修改、破解变难（如 VMProtect、Themida）。</li></ul><p data-src-line="13" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md">两类目的常叠加。对逆向来说，壳是一个障碍：<strong>加了壳的程序，你静态看到的几乎全是壳的代码，真正的逻辑被压缩/加密藏起来了。</strong></p><h2 id="_2-壳的工作原理" tabindex="-1" data-src-line="15" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md">2. 壳的工作原理 <a class="header-anchor" href="#_2-壳的工作原理" aria-label="Permalink to &quot;2. 壳的工作原理&quot;">​</a></h2><p data-src-line="17" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md">不管哪种壳，运行时的基本流程都类似：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>启动 → 壳的入口（stub 解压/解密代码）</span></span>
<span class="line"><span>     → 在内存里还原出原始程序的代码和数据</span></span>
<span class="line"><span>     → 跳转到原始程序的真正入口点（OEP）</span></span>
<span class="line"><span>     → 原始程序正常执行</span></span></code></pre></div><p data-src-line="26" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md">这里有个关键概念：<strong>OEP（Original Entry Point，原始入口点）</strong>。它是加壳前程序真正的入口点，被壳藏了起来。脱壳的目标，就是找到 OEP、把还原后的程序从内存里 dump 出来、并修复它的导入表。</p><p data-src-line="28" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md">理解这个「stub 先跑、还原、再跳 OEP」的流程，是理解一切脱壳方法的基础。</p><h2 id="_3-识别壳" tabindex="-1" data-src-line="30" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md">3. 识别壳 <a class="header-anchor" href="#_3-识别壳" aria-label="Permalink to &quot;3. 识别壳&quot;">​</a></h2><p data-src-line="32" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md">脱壳前先判断「加没加壳、加的什么壳」。几个信号（<a href="./../05-static-analysis/chapter-01-basics.html">静态分析基础</a>也提过）：</p><ul data-src-line="34" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md"><li data-src-line="34" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md"><strong>节区名异常</strong>：如 UPX 的 <code>UPX0</code>、<code>UPX1</code>，或 <code>.packed</code>、<code>.vmp</code> 这类非标准名。</li><li data-src-line="35" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md"><strong>入口点异常</strong>：入口点（entry point）不在 <code>.text</code> 节，而落在某个陌生的节区。</li><li data-src-line="36" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md"><strong>节区属性矛盾</strong>：某个节的 <code>SizeOfRawData</code>（文件里的大小）远小于 <code>VirtualSize</code>（内存里的大小），说明「文件里很小、运行时却要展开」，是压缩壳的典型特征。</li><li data-src-line="37" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md"><strong>工具直接报告</strong>：<strong>Detect It Easy（DIE）</strong> 会自动识别并报出壳名（如 &quot;UPX(3.96)&quot;）。</li></ul><p data-src-line="39" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md">识别出壳的类型后，脱壳策略就清晰了：<strong>有专用脱壳工具的优先用工具；没有的再手动脱。</strong></p><h2 id="_4-常见壳-upx-与它的同类" tabindex="-1" data-src-line="41" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md">4. 常见壳：UPX 与它的同类 <a class="header-anchor" href="#_4-常见壳-upx-与它的同类" aria-label="Permalink to &quot;4. 常见壳：UPX 与它的同类&quot;">​</a></h2><p data-src-line="43" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md"><strong>UPX</strong> 是最常见的开源压缩壳。它的特征是节区名为 <code>UPX0</code>、<code>UPX1</code>，且因为格式公开、自带还原信息，脱壳最简单——<code>upx -d target.exe</code> 一条命令即可。</p><p data-src-line="45" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md">其他常见的压缩壳还有 ASPack、FSG、MPRESS 等，原理与 UPX 类似：压缩代码段，运行时解压到内存，跳回 OEP。这类壳的脱壳难度不高，因为「壳总会把原程序完整还原出来」。</p><p data-src-line="47" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md">对比之下，<a href="./chapter-03-virtualization-anti-debugging.html">虚拟化保护</a>和反调试手段则是另一个量级的难度。</p><h2 id="_5-自动脱壳-优先用现成工具" tabindex="-1" data-src-line="49" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md">5. 自动脱壳：优先用现成工具 <a class="header-anchor" href="#_5-自动脱壳-优先用现成工具" aria-label="Permalink to &quot;5. 自动脱壳：优先用现成工具&quot;">​</a></h2><p data-src-line="51" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md">很多常见壳有成熟的自动脱壳方案，优先使用：</p><ul data-src-line="53" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md"><li data-src-line="53" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md"><strong>UPX</strong>：<code>upx -d target.exe</code>。</li><li data-src-line="54" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md"><strong>通用脱壳插件/脚本</strong>：x64dbg 生态里有针对常见壳的脱壳脚本或插件，能自动完成「找 OEP → dump → 修 IAT」。</li><li data-src-line="55" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md"><strong>专用脱壳机</strong>：针对某些老壳有独立脱壳工具。</li></ul><p data-src-line="57" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md">自动脱壳的优点是快、不易出错。<strong>先试自动，失败再手动</strong>，是务实的顺序。自动脱壳失败通常是因为壳版本更新、或壳本身是「保护壳」而非「压缩壳」。</p><hr><blockquote data-src-line="61" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md"><p data-src-line="61" data-src-file="reverse-engineering/07-packing/chapter-01-packing-principle.md">本章建立的是对壳的基本认识：壳 = 压缩/加密的原始程序 + 一段负责还原的 stub，脱壳的核心是找 OEP。自动工具能处理的优先自动。下一章讲没有现成工具时的办法——<a href="./chapter-02-manual-unpacking.html">手动脱壳</a>。</p></blockquote>`,25)])])}const h=a(c,[["render",p]]);export{k as __pageData,h as default};
